    int n;
    std::cin >> n;

    std::vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        std::cin >> arr[i];
    }

    int minDist = std::numeric_limits<int>::max();
    int prevMinIndex = -1;
    for (int i = 0; i < n; i++) {
        if (arr[i] == *std::min_element(arr.begin(), arr.end())) {
            if (prevMinIndex != -1) {
                minDist = std::min(minDist, i - prevMinIndex);
            }
            prevMinIndex = i;
        }
    }

    std::cout << minDist << std::endl;

    return 0;
}

